/// Single Dart seam for the typed sequencer/run event surface.
///
/// The typed event union (`SkotiqEvent` + `EventPayload_*` variants) and
/// its display helpers are authored in `package:skotiq_bridge` because the
/// union variants are generated by flutter_rust_bridge from the Rust event
/// definitions. App and headless UI code, however, should never reach across to
/// `package:skotiq_bridge` for them — `skotiq_core` is the seam every
/// consumer already depends on, and routing the types through here keeps the
/// bridge an implementation detail of the backend layer.
///
/// This is a clean `export ... show ...` re-export (no wrapper types): the
/// re-exported symbols are the exact bridge types, so values flowing out of
/// [skotiqEventsProvider] and the network/FFI backends are assignable to
/// the names imported from here without any adaptation.
///
/// Note on naming: the wire/JSON event model used across the network boundary
/// (`src/models/backend/event_types.dart`) also defines `SkotiqEvent`,
/// `EventCategory`, and `EventSeverity`, but it is intentionally NOT surfaced
/// through the aggregate barrel — only this typed bridge surface is — so there
/// is no collision for consumers of `package:skotiq_core/skotiq_core.dart`.
library;

export 'package:skotiq_bridge/skotiq_bridge.dart'
    show
        // Top-level typed event + its envelope enums.
        SkotiqEvent,
        EventCategory,
        EventSeverity,
        EventPayload,
        // Payload union variants (one per event family).
        EventPayload_Equipment,
        EventPayload_Imaging,
        EventPayload_Guiding,
        EventPayload_Sequencer,
        EventPayload_Safety,
        EventPayload_System,
        EventPayload_PolarAlignment,
        EventPayload_PolarAlignmentStatus,
        EventPayload_PolarAlignmentImage,
        EventPayload_DepthLock,
        // DepthLock event family. Published under the `imaging` category, so
        // a switch over the payload union needs these to stay exhaustive.
        DepthLockEvent,
        DepthLockEvent_GoalUpdated,
        DepthLockEvent_EvidenceRejected,
        DepthLockEvent_AnalysisDropped,
        DepthLockEvent_GoalChanged,
        // Equipment event family (the payload union exposes these via the
        // `EventPayload_Equipment` arm, so the UI's exhaustive switches need
        // the variants to compile).
        EquipmentEvent,
        EquipmentEvent_Connecting,
        EquipmentEvent_Connected,
        EquipmentEvent_Disconnected,
        EquipmentEvent_PropertyChanged,
        EquipmentEvent_Error,
        EquipmentEvent_MountSlewStarted,
        EquipmentEvent_MountSlewCompleted,
        EquipmentEvent_MountTrackingStarted,
        EquipmentEvent_MountTrackingStopped,
        EquipmentEvent_MountParkStarted,
        EquipmentEvent_MountParkCompleted,
        EquipmentEvent_MountUnparked,
        EquipmentEvent_FocuserMoveStarted,
        EquipmentEvent_FocuserMoveCompleted,
        EquipmentEvent_FocuserTemperatureChanged,
        EquipmentEvent_FilterChanging,
        EquipmentEvent_FilterChanged,
        EquipmentEvent_RotatorMoveStarted,
        EquipmentEvent_RotatorMoveCompleted,
        EquipmentEvent_CameraCoolingStarted,
        EquipmentEvent_CameraCoolingReached,
        EquipmentEvent_CameraWarmingStarted,
        EquipmentEvent_CameraWarmingCompleted,
        EquipmentEvent_HeartbeatStarted,
        EquipmentEvent_HeartbeatStopped,
        EquipmentEvent_HeartbeatStatusChanged,
        EquipmentEvent_HeartbeatReconnecting,
        EquipmentEvent_HeartbeatReconnected,
        EquipmentEvent_DeviceDiscovered,
        EquipmentEvent_DeviceLost,
        HeartbeatStatus,
        // Guiding event family.
        GuidingEvent,
        GuidingEvent_Connected,
        GuidingEvent_Disconnected,
        GuidingEvent_GuidingStarted,
        GuidingEvent_GuidingStopped,
        GuidingEvent_Paused,
        GuidingEvent_Resumed,
        GuidingEvent_Settled,
        GuidingEvent_LostStar,
        GuidingEvent_DitherStarted,
        GuidingEvent_DitherCompleted,
        GuidingEvent_Correction,
        GuidingEvent_Looping,
        GuidingEvent_Settling,
        GuidingEvent_Calibrating,
        GuidingEvent_CalibrationComplete,
        GuidingEvent_StarSelected,
        GuidingEvent_AppState,
        GuidingEvent_GuideStats,
        // Imaging event family.
        ImagingEvent,
        ImagingEvent_ExposureStarted,
        ImagingEvent_ExposureStartedWithFrame,
        ImagingEvent_ExposureProgress,
        ImagingEvent_ExposureCompleted,
        ImagingEvent_ExposureCompletedWithFrame,
        ImagingEvent_ExposureFailed,
        ImagingEvent_ExposureCancelled,
        ImagingEvent_DownloadStarted,
        ImagingEvent_DownloadCompleted,
        ImagingEvent_ImageReady,
        ImagingEvent_ImageSaved,
        ImagingEvent_IntegrationProgress,
        ImagingEvent_TemperatureChanged,
        ImagingEvent_ExposureComplete,
        ImagingEvent_ExposureFailedOld,
        // Safety event family.
        SafetyEvent,
        SafetyEvent_WeatherUnsafe,
        SafetyEvent_WeatherSafe,
        SafetyEvent_EmergencyStop,
        SafetyEvent_ParkInitiated,
        SafetyEvent_ParkCompleted,
        // Sequencer event family — includes the Science / photometry variants
        // added in the Rust/FRB phase (`PhotometryFrame`,
        // `PhotometryCadenceBroken`, `PhotometrySummary`).
        SequencerEvent,
        SequencerEvent_Started,
        SequencerEvent_Paused,
        SequencerEvent_Resumed,
        SequencerEvent_Stopped,
        SequencerEvent_Completed,
        // The terminal-failure variant. Consumers need it by name to tell a
        // NEW failure from the terminal event RESTATING a mid-run
        // `SequencerEvent_Error` reason.
        SequencerEvent_Failed,
        SequencerEvent_NodeStarted,
        SequencerEvent_NodeCompleted,
        SequencerEvent_Progress,
        SequencerEvent_TargetChanged,
        SequencerEvent_TargetCompleted,
        SequencerEvent_ExposureStarted,
        SequencerEvent_ExposureCompleted,
        SequencerEvent_Error,
        SequencerEvent_TriggerFired,
        SequencerEvent_InstructionProgress,
        SequencerEvent_InstructionProgressStructured,
        SequencerEvent_FrameAccepted,
        SequencerEvent_FrameRejected,
        SequencerEvent_SchedulerDecision,
        SequencerEvent_IntegrationBudget,
        SequencerEvent_ExposureAdjusted,
        SequencerEvent_PhotometryFrame,
        SequencerEvent_PhotometryCadenceBroken,
        SequencerEvent_PhotometrySummary,
        SequencerEvent_RecoveryStarted,
        SequencerEvent_RecoveryProgress,
        SequencerEvent_RecoveryCompleted,
        SequencerEvent_RecoveryGaveUp,
        SequencerEvent_PluginNodeRequested,
        SequencerEvent_PluginNodeProgress,
        SequencerEvent_DecisionLogged,
        // A Smart Exposure plan that ended on its DepthLock goal rather than
        // on its frame count.
        SequencerEvent_DepthGoalCompleted,
        // System event family.
        SystemEvent,
        SystemEvent_Initialized,
        SystemEvent_ShuttingDown,
        SystemEvent_Error,
        SystemEvent_DiskSpaceLow,
        SystemEvent_Notification,
        SystemEvent_EventsDropped,
        // Polar-alignment supporting payload types (referenced by the
        // `EventPayload_PolarAlignment*` arms in the display helpers).
        PolarAlignmentEvent,
        PolarAlignmentStatus,
        PolarAlignmentImageEvent,
        // Scheduler decision detail carried by
        // `SequencerEvent_SchedulerDecision.scores`.
        SchedulerScoreEntry,
        // Per-frame capture truth carried by
        // `SequencerEvent_FrameAccepted/FrameRejected.capture`.
        FrameCaptureMetadata,
        // Display helpers + critical-event classification used by the Run
        // Dashboard event feed / banner.
        skotiqEventDisplayTitle,
        skotiqEventDisplayDetail,
        depthGoalCompletedDetail,
        isCriticalEvent;
